import{_ as a,o as t,c as n,a2 as s}from"./chunks/framework.BWTY_seE.js";const m=JSON.parse('{"title":"AI 动态 · 2026-10-29","description":"","frontmatter":{"title":"AI 动态 · 2026-10-29","date":"2026-10-29T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-10/ai-news-2026-10-29.md","filePath":"news/2026-10/ai-news-2026-10-29.md","lastUpdated":null}'),r={name:"news/2026-10/ai-news-2026-10-29.md"};function i(o,e,l,c,p,h){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ai-动态-·-2026-10-29" tabindex="-1">AI 动态 · 2026-10-29 <a class="header-anchor" href="#ai-动态-·-2026-10-29" aria-label="Permalink to &quot;AI 动态 · 2026-10-29&quot;">​</a></h1><blockquote><p>截至 2026-10-29。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="ai-agent-应用-wabi-融资-5500-万美元-估值达-12-5-亿美元" tabindex="-1">AI Agent 应用 Wabi 融资 5500 万美元，估值达 12.5 亿美元 <a class="header-anchor" href="#ai-agent-应用-wabi-融资-5500-万美元-估值达-12-5-亿美元" aria-label="Permalink to &quot;AI Agent 应用 Wabi 融资 5500 万美元，估值达 12.5 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/39d0fcb02b49.jpg" alt="配图"></p><p>主打「构建迷你应用」的 AI 应用 Wabi 现将自己定位为「个人 Agent」，宣布完成 5500 万美元融资，估值达到 12.5 亿美元，跻身独角兽行列。这显示面向消费者的 Agent 产品仍在获得资本追捧。对读者：关注该类产品的留存与付费转化数据，判断个人 Agent 赛道是真实需求还是估值先行。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/29/wabi-the-ai-agent-that-builds-mini-apps-now-valued-at-1-25b-after-latest-round/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="deepgram-收购-pipecat-母公司-daily-强化语音-ai-基础设施" tabindex="-1">Deepgram 收购 Pipecat 母公司 Daily，强化语音 AI 基础设施 <a class="header-anchor" href="#deepgram-收购-pipecat-母公司-daily-强化语音-ai-基础设施" aria-label="Permalink to &quot;Deepgram 收购 Pipecat 母公司 Daily，强化语音 AI 基础设施&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/232bad681f7d.webp" alt="配图"></p><p>语音 AI 公司 Deepgram 宣布收购实时语音与视频基础设施厂商 Daily，后者是开源框架 Pipecat 的打造者。借助 Pipecat，Deepgram 有望更深入理解实时语音与视频链路。对读者：使用 Pipecat 的团队应关注项目治理与路线图变化，提前评估供应商锁定风险。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/29/deepgram-acquires-pipecat-maker-daily-to-bolster-its-voice-ai-infrastructure/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="微软首次披露-azure-单季营收-332-亿美元" tabindex="-1">微软首次披露 Azure 单季营收：332 亿美元 <a class="header-anchor" href="#微软首次披露-azure-单季营收-332-亿美元" aria-label="Permalink to &quot;微软首次披露 Azure 单季营收：332 亿美元&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/52c910959007.png" alt="配图"></p><p>微软首次以美元数字公开 Azure 季度营收，为 332 亿美元，此前一直只披露增速。这一数字让外界首次能直观比较 Azure 与 AWS 的差距。对读者：云厂商竞争加剧通常意味着价格与折扣空间变化，采购谈判前可据此重新评估多云策略。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/28/microsoft-just-shared-azures-actual-revenue-in-dollars-33-2-billion/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="微软单季从-openai-相关安排中获得-100-亿美元收入" tabindex="-1">微软单季从 OpenAI 相关安排中获得 100 亿美元收入 <a class="header-anchor" href="#微软单季从-openai-相关安排中获得-100-亿美元收入" aria-label="Permalink to &quot;微软单季从 OpenAI 相关安排中获得 100 亿美元收入&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/10fb2128df6c.jpg" alt="配图"></p><p>微软表示在截至 9 月 30 日的季度中，从与 OpenAI 的商业安排（含收入分成）中获得 100 亿美元收入，凸显双方合作中仍存在巨大的财务依赖关系。对读者：评估 AI 产业链公司时，需把这种高度集中的收入依赖视为风险因子而非单纯利好。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/10/28/microsoft-recorded-10-billion-in-revenue-from-openai/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p class="news-empty-day" data-i18n="news.emptyDay">（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="google-发布-gemini-4-carbon-新一代前沿模型" tabindex="-1">Google 发布 Gemini 4 Carbon：新一代前沿模型 <a class="header-anchor" href="#google-发布-gemini-4-carbon-新一代前沿模型" aria-label="Permalink to &quot;Google 发布 Gemini 4 Carbon：新一代前沿模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Google DeepMind</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/a4ad91014bf0.webp" alt="配图"></p><p>Google DeepMind 推出 Gemini 4 Carbon，官方称其在网络安全与长程任务能力上达到最强水平，并在更新后更难的基准上重回第一。但 Ars Technica 指出它本质上是 Argon 的略强版本，且初期仅向受审核的网络安全防御方开放，定价为每百万 token 2/10 美元。对读者：能力虽强但可用性受限，选型时先确认自己是否在开放名单内，并预留回退方案。</p><p class="news-entry-source"><a href="https://deepmind.google/blog/gemini-4-carbon-our-next-frontier-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="mistral-开源-le-chonk-mistral-large-4-1t-参数多模态模型" tabindex="-1">Mistral 开源 Le Chonk（Mistral Large 4）：1T 参数多模态模型 <a class="header-anchor" href="#mistral-开源-le-chonk-mistral-large-4-1t-参数多模态模型" aria-label="Permalink to &quot;Mistral 开源 Le Chonk（Mistral Large 4）：1T 参数多模态模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Mistral AI News</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/e462565005a5.jpg" alt="配图"></p><p>Mistral 开放了 Mistral Large 4（代号 Le Chonk）的权重，这是一个 1T 参数的多模态模型，官方称其为最佳开源编码模型，并在欧洲训练完成。Wired 报道称其在编码与网络安全上可匹敌 DeepSeek、Z.ai 的顶尖模型。对读者：若关注可自托管的高端编码模型，值得尽快在自有评测集上验证其真实表现与推理成本。</p><p class="news-entry-source"><a href="https://mistral.ai/news/mistral-large-4-oss" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="gemini-4-carbon-技术细节-intelligence-index-59-分、sec-bench-pro-88-2" tabindex="-1">Gemini 4 Carbon 技术细节：Intelligence Index 59 分、SEC-bench Pro 88.2% <a class="header-anchor" href="#gemini-4-carbon-技术细节-intelligence-index-59-分、sec-bench-pro-88-2" aria-label="Permalink to &quot;Gemini 4 Carbon 技术细节：Intelligence Index 59 分、SEC-bench Pro 88.2%&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-29">2026-10-29</time></p><p>MarkTechPost 汇总了 Gemini 4 Carbon 的关键指标：Artificial Analysis Intelligence Index 得分 59，SEC-bench Pro 达 88.2%，定位为网络安全防御与编码的顶级模型，访问从受审核的防御方开始，价格每百万 token 2/10 美元。对读者：把榜单分数与自身任务分布对齐再决策，安全类场景可优先申请试用。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/28/google-deepmind-gemini-4-carbon-frontier-model/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="assemblyai-推出-tts-1-面向语音-agent-的按字符计费-tts-api" tabindex="-1">AssemblyAI 推出 TTS-1：面向语音 Agent 的按字符计费 TTS API <a class="header-anchor" href="#assemblyai-推出-tts-1-面向语音-agent-的按字符计费-tts-api" aria-label="Permalink to &quot;AssemblyAI 推出 TTS-1：面向语音 Agent 的按字符计费 TTS API&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-29">2026-10-29</time></p><p>AssemblyAI 发布其首个文本转语音模型 AssemblyAI-TTS-1，定价为每百万字符 15 美元，支持无合同的不限并发，首发支持 6 种语言，面向语音 Agent 场景。对读者：构建语音 Agent 时可将它纳入成本对比，尤其关注高并发下的稳定性与多语言覆盖是否够用。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/29/assemblyai-tts-1-text-to-speech-api-voice-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="infini-ai-lab-开源-hermit-agent-的-harness-适配框架" tabindex="-1">Infini-AI-Lab 开源 Hermit：Agent 的 Harness 适配框架 <a class="header-anchor" href="#infini-ai-lab-开源-hermit-agent-的-harness-适配框架" aria-label="Permalink to &quot;Infini-AI-Lab 开源 Hermit：Agent 的 Harness 适配框架&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-29">2026-10-29</time></p><p>Infini-AI-Lab 发布 Apache-2.0 许可的 Hermit，这是一个 harness 适配框架，可从任务反馈中训练外部的指令、技能、记忆与工具层，而无需改动 Agent 的模型与 harness 本身。对读者：想在不动基座模型的前提下提升 Agent 表现，可把它列入实验清单并验证迁移成本。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/29/infini-ai-lab-hermit-harness-adapter-framework/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="minimax-开源-mcode-stack-编码团队日常使用的-agent-技能集" tabindex="-1">MiniMax 开源 MCode Stack：编码团队日常使用的 Agent 技能集 <a class="header-anchor" href="#minimax-开源-mcode-stack-编码团队日常使用的-agent-技能集" aria-label="Permalink to &quot;MiniMax 开源 MCode Stack：编码团队日常使用的 Agent 技能集&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">MarkTechPost</span><time datetime="2026-10-29">2026-10-29</time></p><p>MiniMax 以 MIT 协议开源 MCode Stack，包含 17 个 SKILL.md 技能与 5 份检查清单，覆盖代码评审、子 Agent 拆分、上下文预算与长时命令等其 MiniMax Code 团队日常使用的实践。对读者：可直接借鉴其上下文预算与子 Agent 拆分思路，快速搭建自己的 Agent 工作流。</p><p class="news-entry-source"><a href="https://www.marktechpost.com/2026/10/28/minimax-open-sources-mcode-stack-agent-skills/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-universe-2026-把-github-做成端到端软件交付系统" tabindex="-1">GitHub Universe 2026：把 GitHub 做成端到端软件交付系统 <a class="header-anchor" href="#github-universe-2026-把-github-做成端到端软件交付系统" aria-label="Permalink to &quot;GitHub Universe 2026：把 GitHub 做成端到端软件交付系统&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/4a29bea9c3d5.webp" alt="配图"></p><p>GitHub 在 Universe 大会上阐述了其愿景：成为全球最完整的端到端软件交付系统，覆盖从编码到交付的每一层。这与同期 Octoverse 数据中 Agent 驱动开发的爆发式增长相互呼应。对读者：平台正在向全链路收拢，团队应评估现有 CI/CD 与协作工具是否会被逐步替代。</p><p class="news-entry-source"><a href="https://github.blog/news-insights/company-news/github-universe-2026-evolving-every-layer-of-the-stack/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p><h3 id="octoverse-2026-开发者用-agent-编码-提交与推送创新高" tabindex="-1">Octoverse 2026：开发者用 Agent 编码，提交与推送创新高 <a class="header-anchor" href="#octoverse-2026-开发者用-agent-编码-提交与推送创新高" aria-label="Permalink to &quot;Octoverse 2026：开发者用 Agent 编码，提交与推送创新高&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-10-29">2026-10-29</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-10/0902b41d4708.jpg" alt="配图"></p><p>GitHub 2026 年度 Octoverse 报告显示，随着开发者大量使用 Agent 编码，合并 PR 在不到一年内增至每月 2.2 亿次，提交量超三倍达到每月 73.8 亿次，新仓库创建速率翻倍至每月 3030 万。对读者：代码评审与质量门禁将成为瓶颈，建议提前加强自动化审查与测试覆盖。</p><p class="news-entry-source"><a href="https://github.blog/news-insights/octoverse/octoverse-commits-pushes-reach-new-highs-in-2026-as-developers-build-with-agents/" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="rspack-2-3-发布-联手-swc-团队带来全新编译器" tabindex="-1">Rspack 2.3 发布：联手 SWC 团队带来全新编译器 <a class="header-anchor" href="#rspack-2-3-发布-联手-swc-团队带来全新编译器" aria-label="Permalink to &quot;Rspack 2.3 发布：联手 SWC 团队带来全新编译器&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">掘金前端</span><time datetime="2026-10-29">2026-10-29</time></p><p>Rspack 2.3 发布，集成 SWC Next 解析器，官方称可提升构建速度、降低内存占用并减小产物体积；同时推出实验性新版缓存，支持为 loader 单独缓存转换结果。对读者：构建性能敏感的团队可先在分支上升级验证缓存行为，再决定是否全量切换。</p><p class="news-entry-source"><a href="https://juejin.cn/post/7701932169296003082" target="_blank" rel="noopener noreferrer" data-i18n="news.readOriginal">阅读原文</a></p></div>',8)])])}const g=a(r,[["render",i]]);export{m as __pageData,g as default};
